// Types for core.js, the WebAssembly build of core/ (generated by `node scripts/core.mjs wasm`).
import type { Vec3 } from '../participants';
import type { Waypoint } from '../motion';

interface Deletable {
  delete(): void;
}

export interface WaypointList extends Deletable {
  push_back(waypoint: Waypoint): void;
}

export interface Motion extends Deletable {
  positionAt(t: number): Vec3;
}

export interface CoreModule {
  WaypointList: new () => WaypointList;
  Motion: new (start: Vec3, waypoints: WaypointList) => Motion;
}

export default function createCore(): Promise<CoreModule>;
